// District job weightings (from original static dataset) for proportional share fallback
const DISTRICT_WEIGHTS: Record<string, number> = {
  "Colombo": 5420, "Gampaha": 3180, "Kalutara": 2140,
  "Galle": 2050, "Matara": 1730, "Hambantota": 980,
  "Kegalle": 1290, "Ratnapura": 1870,
  "Badulla": 1410, "Moneragala": 590,
  "Matale": 1560, "Kandy": 2890, "Nuwara Eliya": 1240,
  "Ampara": 1120, "Batticaloa": 890, "Trincomalee": 740,
  "Anuradhapura": 1680, "Polonnaruwa": 680,
  "Puttalam": 1050, "Kurunegala": 2340,
  "Vanni": 720, "Jaffna": 1890
};

const PROVINCE_WEIGHT_SUMS: Record<string, number> = {
  western: 10740, southern: 4760, sabaragamuwa: 3160, uva: 2000,
  central: 5690, eastern: 2750, northcentral: 2360, northwestern: 3390, northern: 2610
};

// Province job resolver
function getProvinceJobs(provinceKey: string, districtGeoData: DistrictGeoNode[]) {
  const provNode = districtGeoData?.find(
    (n) => n.id?.toLowerCase() === provinceKey.toLowerCase() || n.province?.toLowerCase() === PROVINCES[provinceKey]?.label?.toLowerCase()
  );
  if (provNode) return provNode.jobs;

  const districtNodes = districtGeoData?.filter(
    (n) => n.province?.toLowerCase() === provinceKey.toLowerCase()
  );
  if (districtNodes && districtNodes.length > 0) {
    return districtNodes.reduce((sum, n) => sum + n.jobs, 0);
  }
  return 0;
}

// District job resolver (supports direct match or scales province-level metrics proportionally)
function getDistrictJobs(district: (typeof SRI_LANKA_DISTRICTS)[0], districtGeoData: DistrictGeoNode[]) {
  const directMatch = districtGeoData?.find(
    (n) =>
      n.id?.toLowerCase() === district.id?.toLowerCase() ||
      n.id?.toLowerCase() === `district-${district.name.toLowerCase()}` ||
      n.id?.toLowerCase() === district.name.toLowerCase() ||
      n.province?.toLowerCase() === district.name.toLowerCase()
  );
  if (directMatch) return directMatch.jobs;

  const provKey = district.province;
  const provNode = districtGeoData?.find(
    (n) => n.id?.toLowerCase() === provKey.toLowerCase() || n.province?.toLowerCase() === PROVINCES[provKey]?.label?.toLowerCase()
  );
  if (provNode) {
    const totalProvWeight = PROVINCE_WEIGHT_SUMS[provKey] || 1;
    const distWeight = DISTRICT_WEIGHTS[district.name] || 0;
    return Math.round((distWeight / totalProvWeight) * provNode.jobs);
  }
  return 0;
}

// Province aggregation helper using live BFF API data
function getProvinceData(districtGeoData: DistrictGeoNode[]) {
  const map: Record<
    string,
    { label: string; jobs: number; color: string; districts: string[] }
  > = {};
  for (const [key, p] of Object.entries(PROVINCES)) {
    map[key] = {
      label: p.label,
      jobs: getProvinceJobs(key, districtGeoData),
      color: p.color,
      districts: []
    };
  }
  for (const d of SRI_LANKA_DISTRICTS) {
    map[d.province].districts.push(d.name);
  }
  return map;
}

function getDistrictColor(
  district: (typeof SRI_LANKA_DISTRICTS)[0],
  isHovered: boolean,
) {
  if (isHovered) return "#1e40af";
  return PROVINCES[district.province].color;
}

export default function DashboardPage() {
  const { data: dashboardData, isLoading, isError } = useDashboardSummary();

  const [hoveredDistrict, setHoveredDistrict] = useState<
    (typeof SRI_LANKA_DISTRICTS)[0] | null
  >(null);
  const [hoveredProvince, setHoveredProvince] = useState<string | null>(null);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
          <p className="text-sm font-semibold text-gray-500">Loading Dashboard Metrics...</p>
        </div>
      </div>
    );
  }

  if (isError || !dashboardData) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="bg-white p-8 rounded-xl shadow-md max-w-md w-full border border-red-100 flex flex-col items-center text-center gap-4">
          <div className="w-12 h-12 rounded-full bg-red-50 text-red-500 flex items-center justify-center">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
          </div>
          <h3 className="text-lg font-bold text-gray-800">Error Loading Dashboard</h3>
          <p className="text-sm text-gray-500">Unable to retrieve labour market summary. Please check your network connection or try again later.</p>
        </div>
      </div>
    );
  }

  const provinceData = getProvinceData(dashboardData.districtGeoData);

  const activeProvince = hoveredDistrict
    ? hoveredDistrict.province
    : hoveredProvince;

  const totalJobs = dashboardData.districtGeoData.reduce((sum, node) => sum + node.jobs, 0) || 1;
  const maxJobs = Math.max(...SRI_LANKA_DISTRICTS.map((d) => getDistrictJobs(d, dashboardData.districtGeoData))) || 1;

  return (
    <div className="min-h-screen bg-gray-50">
      <Header
        title="Dashboard"
        subtitle="National Labour Market Intelligence — Regional Breakdown Overview"
      />

      <div className="p-8 space-y-6">
        {/* 1. KPI Metric Row */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <KpiCard
            label="Total Jobs Listed"
            value={dashboardData.kpiSummary.totalVacancies.toLocaleString()}
            change={`+${dashboardData.kpiSummary.vacancyGrowthPct}% Month over Month`}
            positive
            icon="briefcase"
          />
          <KpiCard
            label="Categories"
            value={dashboardData.kpiSummary.sectorsTracked.toLocaleString()}
            change="Full island coverage active"
            neutral
            icon="building"
          />
          <KpiCard
            label="Identified Core Skills"
            value={dashboardData.kpiSummary.skillsIdentified.toLocaleString()}
            change="Across active backend structures"
            neutral
            icon="chart"
          />
        </div>

        {/* 2. Map Container & Sector Distribution */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Full Sri Lanka Province Map Panel */}
          <div className="lg:col-span-2 flex flex-col min-h-[520px] relative bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
            <div>
              <h3 className="text-sm font-semibold text-gray-700">
                Sri Lanka — Province-Level Labour Distribution
              </h3>
              <p className="text-xs text-gray-400 mt-0.5">
                Hover over any district to view province vacancy data
              </p>
            </div>

            <div className="flex flex-1 items-center justify-center py-4 relative">
              <svg
                version="1.1"
                xmlns="http://www.w3.org/2000/svg"
                viewBox="0 0 332.068 600"
                preserveAspectRatio="xMidYMid meet"
                className="w-auto max-h-[430px] drop-shadow-lg select-none"
                style={{ overflow: "visible" }}
              >
                {SRI_LANKA_DISTRICTS.map((district) => {
                  const isHovered = hoveredDistrict?.id === district.id;
                  const isProvinceHighlighted =
                    hoveredProvince === district.province && !hoveredDistrict;
                  return (
                    <path
                      key={district.id}
                      d={district.path}
                      fill={getDistrictColor(
                        district,
                        isHovered || isProvinceHighlighted,
                      )}
                      stroke="#ffffff"
                      strokeWidth={
                        isHovered || isProvinceHighlighted ? "2" : "1"
                      }
                      strokeLinejoin="round"
                      strokeOpacity="0.9"
                      fillOpacity={
                        isHovered ? 1 : isProvinceHighlighted ? 0.85 : 0.75
                      }
                      className="cursor-pointer transition-all duration-150"
                      onMouseEnter={() => setHoveredDistrict(district)}
                      onMouseLeave={() => setHoveredDistrict(null)}
                    />
                  );
                })}
              </svg>

              {/* Tooltip / Data Overlay */}
              <div className="absolute bottom-4 right-4 bg-zinc-950 text-white p-4 rounded-xl shadow-2xl border border-zinc-800 min-w-[240px] pointer-events-none transition-all duration-200">
                <p className="text-[9px] text-zinc-500 font-mono uppercase tracking-widest">
                  Live Province Data
                </p>
                {hoveredDistrict ? (
                  <>
                    <div className="flex items-center gap-2 mt-1">
                      <span
                        className="w-2.5 h-2.5 rounded-full flex-shrink-0"
                        style={{
                          backgroundColor:
                            PROVINCES[hoveredDistrict.province].color,
                        }}
                      />
                      <h4 className="text-sm font-bold text-white">
                        {PROVINCES[hoveredDistrict.province].label} Province
                      </h4>
                    </div>
                  </>
                ) : (
                  <h4 className="text-sm font-bold mt-1 text-white">
                    All Provinces
                  </h4>
                )}
                <div className="h-px bg-zinc-800 my-2" />
                <div className="space-y-1.5">
                  <p className="text-xs text-zinc-300 flex justify-between items-center">
                    <span>{hoveredDistrict ? `${hoveredDistrict.name} District` : "Total Jobs:"}</span>
                    {!hoveredDistrict && (
                      <span className="font-mono text-blue-400 font-bold text-sm">
                        {totalJobs.toLocaleString()}
                      </span>
                    )}
                    {/* <span className="font-mono text-blue-400 font-bold text-sm">
                      {hoveredDistrict
                        ? getDistrictJobs(hoveredDistrict, dashboardData.districtGeoData).toLocaleString()
                        : totalJobs.toLocaleString()}
                    </span> */}
                  </p>
                  {hoveredDistrict && (
                    <>
                      <p className="text-xs text-zinc-300 flex justify-between items-center">
                        <span>Province Total:</span>
                        <span className="font-mono text-emerald-400 font-bold">
                          {provinceData[
                            hoveredDistrict.province
                          ].jobs.toLocaleString()}
                        </span>
                      </p>
                      <p className="text-xs text-zinc-300 flex justify-between items-center">
                        <span>National Share:</span>
                        <span className="font-mono text-amber-400 font-bold">
                          {(
                            (provinceData[hoveredDistrict.province].jobs /
                              totalJobs) *
                            100
                          ).toFixed(1)}
                          %
                        </span>
                      </p>
                    </>
                  )}
                </div>
                {!hoveredDistrict && (
                  <p className="text-[10px] text-zinc-500 mt-2 font-mono">
                    9 provinces · {totalJobs.toLocaleString()} jobs tracked
                  </p>
                )}
              </div>

              {/* Province Legend */}
              <div className="absolute top-4 left-4 bg-white/95 backdrop-blur-sm border border-gray-100 rounded-lg p-3 shadow-sm">
                <p className="text-[9px] font-semibold text-gray-500 uppercase tracking-wider mb-2">
                  Provinces
                </p>
                <div className="flex flex-col gap-1">
                  {Object.entries(PROVINCES).map(([key, p]) => (
                    <div
                      key={key}
                      className="flex items-center gap-1.5 cursor-pointer group"
                      onMouseEnter={() => setHoveredProvince(key)}
                      onMouseLeave={() => setHoveredProvince(null)}
                    >
                      <div
                        className="w-2.5 h-2.5 rounded-sm flex-shrink-0 transition-transform group-hover:scale-110"
                        style={{ backgroundColor: p.color }}
                      />
                      <span
                        className={`text-[10px] transition-colors ${hoveredProvince === key ? "text-gray-900 font-semibold" : "text-gray-600"}`}
                      >
                        {p.label}
                      </span>
                      <span className="text-[9px] font-mono text-gray-400 ml-auto pl-2">
                        {provinceData[key].jobs.toLocaleString()}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Sector Share + Province Distribution */}
          <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex flex-col h-full min-h-[350px]">
            <h3 className="text-sm font-semibold text-gray-700 mb-2">
              Sector Distribution
            </h3>

            {/* Flex container that grows to pull the chart into all available card space */}
            <div className="flex-1 w-full relative">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart margin={{ top: 0, right: 0, bottom: 0, left: 0 }}>
                  <Pie
                    data={dashboardData.categoryData.slice(0, 5)}
                    cx="50%"
                    cy="40%" // Pulled slightly up to give the bottom legend breathing room
                    innerRadius={80}
                    outerRadius={120}
                    paddingAngle={0}
                    dataKey="vacancies"
                    nameKey="category"
                  >
                    {dashboardData.categoryData.slice(0, 5).map((_, i) => (
                      <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />
                    ))}
                  </Pie>
                  <Legend
                    verticalAlign="bottom"
                    align="center"
                    iconSize={8}
                    iconType="circle"
                    wrapperStyle={{ fontSize: 11, paddingTop: "12px" }}
                  />
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>

        {/* 3. Trends & Ingestion Panel Row */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex flex-col justify-between">
            <div>
              <h3 className="text-sm font-semibold text-gray-700">
                Overall Vacancy Trend (12 Months Summary)
              </h3>
              <p className="text-xs text-gray-400 mt-0.5 mb-4">
                Historical monthly volume breakdown of active vacancies
              </p>
            </div>
            <ResponsiveContainer width="100%" height={260}>
              <AreaChart data={dashboardData.monthlyTrends}>
                <defs>
                  <linearGradient id="gVac" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.15} />
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis dataKey="month" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} />
                <Tooltip />
                <Area
                  type="monotone"
                  dataKey="vacancies"
                  stroke="#3b82f6"
                  fill="url(#gVac)"
                  name="Vacancies"
                />
              </AreaChart>
            </ResponsiveContainer>

            <div className="mt-6 pt-6 border-t border-gray-100 grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <h4 className="text-xs font-semibold text-gray-600 mb-2.5 flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 rounded-full bg-blue-500" />
                  Primary Scraping Ingestion Nodes
                </h4>
                <ResponsiveContainer width="100%" height={130}>
                  <BarChart
                    data={dashboardData.ingestionSources}
                    layout="vertical"
                    margin={{ left: -10, right: 10 }}
                  >
                    <CartesianGrid
                      strokeDasharray="3 3"
                      horizontal={false}
                      stroke="#f5f5f5"
                    />
                    <XAxis type="number" hide />
                    <YAxis
                      dataKey="name"
                      type="category"
                      tick={{ fontSize: 10, fill: "#6b7280" }}
                      axisLine={false}
                      tickLine={false}
                    />
                    <Tooltip
                      formatter={(value) => [`${value} Listed`, "Volume"]}
                    />
                    <Bar dataKey="vacancies" radius={[0, 4, 4, 0]} barSize={12}>
                      {dashboardData.ingestionSources.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={INGESTION_FILL[index % INGESTION_FILL.length]} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>

              <div>
                <h4 className="text-xs font-semibold text-gray-600 mb-2.5 flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                  Leading Volume Broadcasters
                </h4>
                <div className="space-y-1.5 max-h-[130px] overflow-y-auto pr-1">
                  {dashboardData.leadingEmployers.map((employer, idx) => (
                    <div
                      key={employer.name}
                      className="flex items-center justify-between p-2 rounded-lg bg-gray-50 border border-gray-100 hover:bg-gray-100 transition-colors"
                    >
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] font-mono font-bold text-gray-400 w-4">
                          0{idx + 1}
                        </span>
                        <div>
                          <p className="text-xs font-semibold text-gray-700 leading-tight">
                            {employer.name}
                          </p>
                          <p className="text-[9px] text-gray-400 font-medium">
                            {employer.sector}
                          </p>
                        </div>
                      </div>
                      <span className="text-xs font-mono font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full">
                        {employer.openRoles} Posts
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* 4. Progress Tracks Panel */}
          <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
              <h3 className="text-sm font-semibold text-gray-700 mb-3">
                Seniority Level
              </h3>
              <div className="space-y-2.5">
                {dashboardData.distributionTracks.seniority.slice(0, 4).map((s) => (
                  <div key={s.name}>
                    <div className="flex justify-between text-xs mb-1">
                      <span className="text-gray-600 font-medium">
                        {s.name}
                      </span>
                      <span className="text-gray-500 font-mono">
                        {s.share}%
                      </span>
                    </div>
                    <div className="w-full h-2 bg-gray-100 rounded-full">
                      <div
                        className="h-2 bg-blue-500 rounded-full"
                        style={{ width: `${s.share}%` }}
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
              <h3 className="text-sm font-semibold text-gray-700 mb-3">
                Contract Type
              </h3>
              <div className="space-y-2.5">
                {dashboardData.distributionTracks.contractTypes.map((ct) => (
                  <div key={ct.name}>
                    <div className="flex justify-between text-xs mb-1">
                      <span className="text-gray-600 font-medium">
                        {ct.name}
                      </span>
                      <span className="text-gray-500 font-mono">
                        {ct.share}%
                      </span>
                    </div>
                    <div className="w-full h-2 bg-gray-100 rounded-full">
                      <div
                        className="h-2 bg-emerald-500 rounded-full"
                        style={{ width: `${ct.share}%` }}
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm">
              <h3 className="text-sm font-semibold text-gray-700 mb-3">
                Remote Configuration
              </h3>
              <div className="space-y-2.5">
                {dashboardData.distributionTracks.remoteConfiguration.map((rem, index) => (
                  <div key={rem.name}>
                    <div className="flex justify-between text-xs mb-1">
                      <span className="text-gray-600 font-medium">
                        {rem.name}
                      </span>
                      <span className="text-gray-500 font-mono">
                        {rem.share}%
                      </span>
                    </div>
                    <div className="w-full h-2 bg-gray-100 rounded-full">
                      <div
                        className={`h-2 ${index === 0 ? "bg-indigo-500" : "bg-purple-500"} rounded-full`}
                        style={{ width: `${rem.share}%` }}
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function KpiCard({
  label,
  value,
  change,
  positive,
  neutral,
  icon,
}: {
  label: string;
  value: string;
  change: string;
  positive?: boolean;
  neutral?: boolean;
  icon: string;
}) {
  const iconBg =
    icon === "briefcase"
      ? "bg-blue-50 text-blue-600"
      : icon === "building"
        ? "bg-emerald-50 text-emerald-600"
        : "bg-violet-50 text-violet-600";

  return (
    <div className="bg-white p-5 rounded-xl border border-gray-100 shadow-sm flex flex-col justify-between">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-xs text-gray-500 font-medium uppercase tracking-wider">
            {label}
          </p>
          <p className="text-2xl font-bold text-gray-900 mt-1">{value}</p>
        </div>
        <div
          className={`w-10 h-10 rounded-lg flex items-center justify-center ${iconBg}`}
        >
          {icon === "briefcase" && (
            <svg
              className="w-5 h-5"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
            >
              <rect x="2" y="7" width="20" height="14" rx="2" />
              <path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2" />
            </svg>
          )}
          {icon === "building" && (
            <svg
              className="w-5 h-5"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
            >
              <rect x="4" y="2" width="16" height="20" rx="2" />
              <path d="M9 22v-4h6v4" />
              <path d="M8 6h.01M16 6h.01M12 6h.01M8 10h.01M16 10h.01M12 10h.01M8 14h.01M16 14h.01M12 14h.01" />
            </svg>
          )}
          {icon === "chart" && (
            <svg
              className="w-5 h-5"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
            >
              <path d="M3 3v18h18" />
              <path d="M18 17V9" />
              <path d="M13 17V5" />
              <path d="M8 17v-3" />
            </svg>
          )}
        </div>
      </div>
      <p
        className={`text-xs mt-3 font-medium ${neutral ? "text-gray-400" : positive ? "text-emerald-600" : "text-red-600"}`}
      >
        {change}
      </p>
    </div>
  );
}
